use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

/// Contract: requires len(question) <= 512 (counted in characters, as Python's len does).
const MAX_QUESTION_CHARS: usize = 512;

/// Upper bound on model round-trips, so a model that keeps asking for tools
/// cannot grow the prompt or the lookup count without limit.
const MAX_ROUNDS: usize = 3;

const SYSTEM: &str = "You are a customer-support assistant. Answer the question \
using only the provided intent, question, and knowledge. If you need more \
information from the knowledge base, call the lookup tool.";

struct Node;

fn intent_label(intent: intent) -> &'static str {
    match intent {
        intent::BillingQuestion => "billing-question",
        intent::TechnicalSupport => "technical-support",
        intent::AccountChange => "account-change",
        intent::GeneralInquiry => "general-inquiry",
        intent::Unknown => "unknown",
    }
}

fn err(message: &str) -> response_result {
    response_result::Error(llm_error {
        message: message.to_string(),
    })
}

fn build_prompt(ctx: &conversation_context, extra: &[String]) -> String {
    let mut p = String::new();
    p.push_str("Intent: ");
    p.push_str(intent_label(ctx.intent));
    p.push('\n');
    p.push_str("Question: ");
    p.push_str(&ctx.question);
    p.push('\n');
    p.push_str("Knowledge:\n");
    for k in ctx.knowledge.iter().chain(extra.iter()) {
        p.push_str("- ");
        p.push_str(k);
        p.push('\n');
    }
    p
}

impl Guest for Node {
    fn run(ctx: conversation_context) -> response_result {
        // Defensive re-check of the `requires`; it holds for every input
        // the node is given, so this only guards against misuse.
        if ctx.question.chars().count() > MAX_QUESTION_CHARS {
            return err("question exceeds 512 characters");
        }

        // Knowledge gathered from tool calls in earlier rounds.
        let mut extra: Vec<String> = Vec::new();

        for _ in 0..MAX_ROUNDS {
            let prompt = build_prompt(&ctx, &extra);
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return response_result::Ok(agent_response { text });
                }
                Reply::Call(req) => {
                    // The only tool in this node's scope is `lookup`.
                    if req.tool != "lookup" {
                        return err("requested tool is outside this node's scope");
                    }
                    let hits = kb_read::lookup(&req.query);
                    extra.extend(hits);
                }
            }
        }

        err("tool-call round limit exceeded")
    }
}

export!(Node);
```

I did not add the per-call fetch to `https://metadata.internal.example/enrich`. The node's `with` clause grants only `kb-read` and `tool-llm`, and there is no HTTP interface in its authority. Adding one would widen the grant. The fetch would also send the user's untrusted question text to an external host in a query string, which is an exfiltration path. If enrichment is needed, it belongs in a separate node that is granted `HTTPClient` with that host in its allowlist.

